// ===== Job Scout: normalise, score and filter remote job offers =====
// Input: raw items from the Remotive, Remote OK, Jobicy and Himalayas APIs.
// Output: one item { count, scanned, relevant, text (Telegram HTML), offers[] }.

const KEYWORDS = {
  'n8n': 12, 'zapier': 8, 'make.com': 8, 'workflow automation': 8, 'automation': 6,
  'no-code': 7, 'nocode': 7, 'low-code': 5, 'airtable': 5, 'ai agent': 6, 'llm': 4,
  'prompt': 5, 'claude': 5, 'chatgpt': 4, 'ai trainer': 8, 'annotation': 5, 'rlhf': 5,
  'french': 8, 'francophone': 8, 'video editor': 8, 'video editing': 6, 'motion': 8,
  'capcut': 6, 'content creator': 7, 'social media': 6, 'community manager': 6,
  'canva': 5, 'marketing assistant': 7, 'virtual assistant': 6, 'operations assistant': 6,
  'next.js': 4, 'typescript': 3, 'junior': 5, 'entry level': 5, 'part-time': 5,
  'part time': 5, 'freelance': 5, 'contract': 3, 'asynchronous': 5, 'async': 4,
};
const TITLE_BONUS = ['n8n', 'automation', 'ai', 'video', 'motion', 'content', 'social',
  'marketing', 'assistant', 'junior', 'french', 'no-code', 'editor'];
const SENIOR = ['senior', 'sr.', 'sr ', 'lead', 'principal', 'head of', 'director', 'staff ',
  'vp ', 'chief', 'architect', 'manager'];
const SPOKEN = ['phone calls', 'cold call', 'on the phones', 'sales calls', 'fluent spoken english'];
const BLOCKED_GEO = ['usa', 'united states', 'us only', 'u.s.', 'canada', 'united kingdom', 'uk only',
  'europe', 'germany', 'france', 'spain', 'australia', 'india', 'latam', 'latin america',
  'americas', 'philippines', 'brazil', 'mexico', 'poland', 'netherlands', 'portugal',
  'north america', 'singapore', 'toronto', 'texas', 'california', 'new york'];
const CORE = ['n8n','zapier','make.com','automation','no-code','ai agent','llm','prompt','ai trainer','annotation','french','video editor','video editing','motion','content creator','social media','community manager','canva','marketing assistant','virtual assistant'];
const MIN_SCORE = 18;
const MAX_RESULTS = 8;

const strip = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' ')
  .replace(/\s+/g, ' ').trim();

function normalise(x) {
  if (!x || typeof x !== 'object' || x.legal) return null;
  if (x.position) return { // Remote OK
    source: 'Remote OK', title: x.position, company: x.company, url: x.url || x.apply_url,
    location: x.location || '', salary: x.salary_min ? `${x.salary_min}-${x.salary_max} USD/yr` : '',
    date: String(x.date || '').slice(0, 10), text: (x.tags || []).join(' ') + ' ' + strip(x.description) };
  if (x.jobTitle) return { // Jobicy
    source: 'Jobicy', title: x.jobTitle, company: x.companyName, url: x.url, location: x.jobGeo || '',
    salary: x.annualSalaryMin ? `${x.annualSalaryMin}-${x.annualSalaryMax} ${x.salaryCurrency || ''}/yr` : '',
    date: String(x.pubDate || '').slice(0, 10),
    text: [].concat(x.jobType || [], x.jobIndustry || [], x.jobLevel || '').join(' ') + ' ' + strip(x.jobDescription || x.jobExcerpt) };
  if (x.company_name) return { // Remotive
    source: 'Remotive', title: x.title, company: x.company_name, url: x.url,
    location: x.candidate_required_location || '', salary: x.salary || '',
    date: String(x.publication_date || '').slice(0, 10),
    text: (x.tags || []).join(' ') + ' ' + (x.job_type || '') + ' ' + strip(x.description) };
  if (x.companyName && x.title) { // Himalayas
    const geo = (x.locationRestrictions || []).join(', ');
    return { source: 'Himalayas', title: x.title, company: x.companyName,
      url: x.applicationLink || x.guid, location: geo || 'Worldwide',
      salary: x.minSalary ? `${x.minSalary}-${x.maxSalary} ${x.currency || ''}` : '',
      date: typeof x.pubDate === 'number' ? new Date(x.pubDate * 1000).toISOString().slice(0, 10) : String(x.pubDate || '').slice(0, 10),
      text: [].concat(x.categories || [], x.seniority || [], x.employmentType || '').join(' ') + ' ' + strip(x.description || x.excerpt) };
  }
  return null;
}

function geoStatus(job) {
  const loc = job.location.toLowerCase();
  const body = job.text.toLowerCase();
  if (/(côte d.ivoire|cote d.ivoire|ivory coast|africa|afrique)/.test(loc)) return 'OK';
  const based = body.match(/([a-z]+)[- ]based (candidates|applicants|talent)/);
  if (based && !/(africa|ivoire|worldwide|globally)/.test(based[1])) return 'NO';
  if (/(must be based in|must reside in|only candidates (from|in))/.test(body)) return 'CHECK';
  if (BLOCKED_GEO.some((b) => loc.includes(b))) return 'NO';
  if (!loc || /(worldwide|anywhere|global|^remote$)/.test(loc)) return 'OK';
  if (/(emea|international|multiple)/.test(loc)) return 'CHECK';
  return 'NO'; // limited to one specific country or city
}

function score(job) {
  const t = (job.title + ' ' + job.text).toLowerCase();
  const title = job.title.toLowerCase();
  let s = 0; const why = [];
  const has = (k) => new RegExp(`(^|[^a-z])${k.replace(/[.+]/g, '\for (const [k, w] of Object.entries(KEYWORDS)) if (t.includes(k)) { s += w; why.push(k); }')}([^a-z]|$)`).test(t);
  for (const [k, w] of Object.entries(KEYWORDS)) if (has(k)) { s += w; why.push(k); }
  if (!CORE.some(has)) s = Math.min(s, 0);
  for (const k of TITLE_BONUS) if (new RegExp(`\\b${k}\\b`).test(title)) s += 4;
  if (SENIOR.some((k) => title.includes(k))) { s -= 40; why.push('-senior'); }
  if (SPOKEN.some((k) => t.includes(k))) { s -= 10; why.push('-calls/spoken English'); }
  return { score: s, why: why.slice(0, 6) };
}

// 1. Flatten all API responses
const raw = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j.jobs)) raw.push(...j.jobs); else raw.push(j);
}

// 2. Normalise, deduplicate within this run, score, filter
const seenNow = new Set(); const offers = [];
for (const x of raw) {
  const job = normalise(x);
  if (!job || !job.title || !job.url) continue;
  const key = (job.title + '|' + job.company).toLowerCase();
  if (seenNow.has(key)) continue; seenNow.add(key);
  job.geo = geoStatus(job);
  if (job.geo === 'NO') continue;
  Object.assign(job, score(job));
  if (job.score < MIN_SCORE) continue;
  delete job.text;
  offers.push(job);
}
offers.sort((a, b) => b.score - a.score);

// 3. Skip offers already sent in the last 30 days.
//    Only scheduled runs mark offers as sent, so manual tests never hide offers.
const scheduled = typeof $execution !== 'undefined' && $execution.mode === 'trigger';
const store = $getWorkflowStaticData('global');
store.sent = store.sent || {};
const now = Date.now(); const MONTH = 30 * 24 * 3600 * 1000;
for (const [u, ts] of Object.entries(store.sent)) if (now - ts > MONTH) delete store.sent[u];
const fresh = offers.filter((o) => !store.sent[o.url]).slice(0, MAX_RESULTS);
if (scheduled) for (const o of fresh) store.sent[o.url] = now;

// 4. Build the Telegram message (HTML parse mode)
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = [`<b>Job Scout - ${new Date().toISOString().slice(0, 10)}</b>`,
  `${raw.length} offers scanned, ${offers.length} relevant, ${fresh.length} new`, ''];
fresh.forEach((o, i) => {
  lines.push(`<b>${i + 1}. ${esc(o.title)}</b> - ${esc(o.company)}`);
  lines.push(`Score ${o.score} | Geo: ${o.geo === 'OK' ? 'open' : 'to check'} (${esc(o.location || 'not stated')})` +
    (o.salary ? ` | ${esc(o.salary)}` : ''));
  lines.push(`Match: ${esc(o.why.join(', '))}`);
  lines.push(`<a href="${esc(o.url)}">Open offer</a> (${esc(o.source)})`, '');
});
if (!fresh.length) lines.push('No new relevant offer today.');

return [{ json: { count: fresh.length, scanned: raw.length, relevant: offers.length,
  text: lines.join('\n').slice(0, 4000), offers: fresh } }];
